css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:130px}
*,*::before,*::after{box-sizing:inherit}
[hidden]{display:none!important}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased}
h1,h2,h3,h4,h5{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.12;letter-spacing:-.02em}
p{margin:0}a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
section{padding:88px 0}
.dark{background:var(--k);color:#fff}.dark2{background:var(--k2);color:#fff}.grey{background:var(--g)}
.dark p,.dark2 p{color:var(--dmute)}
.sh{max-width:640px;margin-bottom:44px}
.sh h2{font-size:clamp(28px,4vw,42px)}
.sh p{margin-top:14px;color:var(--mute);font-size:17px}
.dark .sh p,.dark2 .sh p{color:var(--dmute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}
.b-l{background:var(--l);color:var(--k)}
.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}
.b-d{background:var(--k);color:#fff}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
.fine{margin-top:20px;font-size:14px;color:var(--mute)}.dark2 .fine{color:var(--dmute)}
nav{position:sticky;top:0;z-index:30;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-size:14.5px;color:#d0d0d4}
nav ul a:hover,nav ul a.on{color:var(--l)}
nav .btn{padding:10px 18px;font-size:14px}
/* hero */
.hero{padding:80px 0 72px}
.lab{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;color:var(--l);margin-bottom:22px}
.lab::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.hero h1{font-size:clamp(34px,5.2vw,68px);line-height:1.03;letter-spacing:-.038em;max-width:940px}
.hero .sub{margin:22px 0 32px;font-size:clamp(17px,2vw,19px);max-width:540px;color:#d6d6da}
/* filters */
.fbar{position:sticky;top:68px;z-index:25;background:#f7f7f5f2;border-bottom:1px solid var(--line)}
.fbar .wrap{display:flex;gap:10px;padding-top:14px;padding-bottom:14px;overflow-x:auto;scrollbar-width:none}
.fbar button{flex:none;font:600 14px Inter;padding:10px 20px;border-radius:99px;border:1.5px solid var(--line);background:#fff;color:var(--ink);cursor:pointer;transition:background .15s}
.fbar button:hover{border-color:var(--k)}
.fbar button[aria-pressed="true"]{background:var(--k);border-color:var(--k);color:var(--l)}
/* project sections */
.pj{padding:88px 0}
.pj.dk{background:var(--k);color:#fff}.pj.lt{background:var(--w);color:var(--ink)}
.pj .wrap{display:grid;grid-template-columns:1fr 1.35fr;gap:56px;align-items:center}
.pj.rev .tx{order:2}
.cpl{display:inline-block;font:600 12.5px Inter;background:var(--l);color:var(--k);padding:6px 14px;border-radius:99px;margin-bottom:20px}
.pj h2{font-size:clamp(30px,3.6vw,46px);letter-spacing:-.03em;margin-bottom:10px}
.ind{font:600 14px Inter;margin-bottom:20px}.dk .ind{color:var(--l)}.lt .ind{color:var(--mute)}
.pj .ch{font-size:16.5px;margin-bottom:20px;max-width:460px}.lt .ch{color:var(--mute)}.dk .ch{color:#c8c8cc}
.pj ul.pts{list-style:none;margin:0 0 22px;padding:0}
.pts li{padding:10px 0;border-top:1px solid var(--line);font-size:15px}.dk .pts li{border-color:var(--dline);color:#d8d8dc}
.pts li:last-child{border-bottom:1px solid var(--line)}.dk .pts li:last-child{border-color:var(--dline)}
.sv{list-style:none;margin:0 0 26px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.sv li{font-size:12.5px;font-weight:500;padding:5px 12px;border-radius:99px}.lt .sv li{background:var(--g)}.dk .sv li{background:#1c1c20;border:1px solid var(--dline);color:#e0e0e4}
.cs{display:inline-flex;gap:6px;font-weight:600;font-size:15px;border-bottom:2px solid var(--l);padding-bottom:2px}
.nt{margin-top:14px;font-size:13px}.lt .nt{color:var(--mute)}.dk .nt{color:var(--dmute)}
.stg{border-radius:28px;padding:34px;position:relative;overflow:hidden;min-height:480px;display:flex;align-items:center;justify-content:center}
.lt .stg{background:var(--k)}.dk .stg{background:radial-gradient(circle at 70% 20%,#1c1c20,#0e0e10 70%);border:1px solid var(--dline)}
/* frame */
.br{background:var(--k2);border:1px solid var(--dline);border-radius:16px;box-shadow:0 24px 50px #000a;overflow:hidden;width:100%;position:relative}
.top{display:flex;align-items:center;gap:6px;padding:11px 14px;border-bottom:1px solid var(--dline)}
.top b{width:9px;height:9px;border-radius:50%;background:#333}
.top .url{margin-left:12px;font-size:12px;color:var(--dmute);background:#1a1a1e;border-radius:99px;padding:4px 14px}
.pill{display:inline-block;padding:7px 14px;border-radius:99px;background:var(--l);color:var(--k);font:600 11.5px Inter;white-space:nowrap}
.fd{padding:9px 10px;border-radius:9px;background:#17171a;border:1px solid var(--dline);font-size:11px;color:var(--dmute)}.fd b{display:block;font:600 15px Sora;color:#fff}
.rw{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;background:#17171a;border:1px solid var(--dline);font-size:11.5px;color:#ddd}
.rw .av{width:22px;height:22px;border-radius:50%;background:#2a2a2e;flex:none}.rw .ln{flex:1}.rw .pill{margin-left:auto}
.ln{height:7px;border-radius:4px;background:#2a2a2e}
.dsh{display:grid;grid-template-columns:54px 1fr;min-height:330px}
.sd{border-right:1px solid var(--dline);padding:16px 0;display:flex;flex-direction:column;align-items:center;gap:14px}.sd i{width:22px;height:22px;border-radius:7px;background:#2a2a2e}.sd i:first-child{background:var(--l)}
.mn{padding:18px;display:flex;flex-direction:column;gap:10px}.mn h5{font-size:14px;color:#fff}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.tag{font-size:10.5px;padding:3px 9px;border-radius:99px;background:#222226;color:var(--dmute);margin-left:auto;white-space:nowrap}
/* phones */
.ph{--pw:210px;width:var(--pw);aspect-ratio:9/18.5;background:#1a1a1e;border:2px solid #34343a;border-radius:34px;padding:8px;box-shadow:0 24px 50px #000a;position:relative;flex:none}
.sc{height:100%;background:var(--w);border-radius:26px;overflow:hidden;color:var(--ink);padding:2.6em 1.1em 1em;font-size:calc(var(--pw)/20);display:flex;flex-direction:column;gap:.7em;position:relative;line-height:1.35}
.sc::before{content:"";position:absolute;top:.8em;left:50%;transform:translateX(-50%);width:5em;height:1.3em;border-radius:1em;background:#111}
.sc h5{font-size:1.35em}
.chips{display:flex;gap:.5em}.chips i{font-style:normal;flex:1;text-align:center;padding:.5em 0;border-radius:.8em;background:var(--g);font-weight:500}.chips i.on{background:var(--k);color:var(--l)}
.it{display:flex;justify-content:space-between;align-items:center;gap:.5em;padding:.9em;border:1px solid var(--line);border-radius:1em;background:#fff}
.it span{color:var(--mute);font-size:.9em}.it.on{border-color:var(--k);box-shadow:0 0 0 .2em #C7FF3F88}
.bt{margin-top:auto;background:var(--k);color:#fff;text-align:center;padding:.95em;border-radius:99px;font-weight:600}
.cd{background:var(--k);color:#fff;border-radius:1.1em;padding:1em}.cd span{display:block;color:#aaa;font-size:.9em}.cd b{font:600 1.15em Sora}
.im{height:6em;border-radius:1em;background:linear-gradient(135deg,#dcdfd8,#c8ccc3);position:relative}.im b{position:absolute;left:.7em;bottom:.6em;font-size:1em;font-weight:600;color:#222}
.ok{width:4em;height:4em;border-radius:50%;background:var(--l);margin:1.5em auto .5em;display:grid;place-items:center;font:700 1.8em Inter;color:var(--k)}
/* gym overlay */
.gym .ph{position:absolute;right:-6px;bottom:-60px;--pw:176px;transform:rotate(3deg)}
.gym .br{width:88%;margin-right:auto}
/* hotel site */
.site{background:var(--w);color:var(--ink);padding-bottom:20px}
.sn{display:flex;justify-content:space-between;align-items:center;padding:13px 22px;font-size:12px;border-bottom:1px solid var(--line)}.sn b{font:700 14px Sora}.sn span{color:var(--mute);margin-left:16px}.sn em{font-style:normal;background:var(--k);color:#fff;padding:6px 13px;border-radius:99px;font-weight:600}
.hh{margin:18px 22px 0;border-radius:14px;background:linear-gradient(160deg,#1b1b1f,#0c0c0e);color:#fff;padding:30px 26px 50px;position:relative}
.hh h3{font-size:26px;max-width:320px;letter-spacing:-.03em}.hh p{font-size:12.5px;color:#bbb;margin-top:8px;max-width:280px}
.bk{position:absolute;left:18px;right:18px;bottom:-24px;background:#fff;color:var(--ink);border-radius:12px;padding:12px 16px;display:grid;grid-template-columns:repeat(3,1fr) auto;gap:12px;font-size:11px;box-shadow:0 14px 30px #0004;align-items:center}
.bk span{color:var(--mute);display:block;font-size:10px}.bk b{font-weight:600}
.rms{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:46px 22px 0}
.rms div{border:1px solid var(--line);border-radius:10px;padding:10px;font-size:11.5px;font-weight:600;background:#fff}.rms i{display:block;height:50px;border-radius:6px;background:var(--g);margin-bottom:8px}
.chip{position:absolute;right:16px;top:60px;background:var(--k);border:1px solid var(--l);color:#fff;font-size:11.5px;padding:8px 13px;border-radius:99px;display:flex;gap:8px;align-items:center;box-shadow:0 10px 24px #0006;z-index:2}
.chip::before{content:"";width:8px;height:8px;border-radius:50%;background:#25D366}
/* car phones */
.cars{display:flex;gap:14px;align-items:center}.cars .ph{--pw:190px}.cars .ph:nth-child(2){--pw:210px;margin-top:-30px}
/* strip */
.strip{padding:56px 0}
.sp{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:20px;align-items:start}
.sp h3{font-size:clamp(26px,3vw,36px);color:var(--l);margin-bottom:8px}.sp p{font-size:14.5px;max-width:280px}.sp small{display:block;margin-top:10px;font-size:12.5px;color:#d8d8dc}
.sp .arr{color:var(--l);font:600 26px Sora;align-self:center}
/* more */
.more{padding:64px 0}
.mb{border:1.5px dashed #c9cac6;border-radius:24px;padding:36px;display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap}
.mb h3{font-size:22px;margin-bottom:6px}.mb p{color:var(--mute);max-width:560px}
/* approach */
.pr{border-top:1px solid var(--line)}
.pr .row{display:grid;grid-template-columns:.9fr 1.4fr;gap:32px;padding:26px 0;border-bottom:1px solid var(--line);align-items:start}
.pr h3{font-size:20px}.pr p{color:var(--mute);max-width:560px}
/* tech */
.tk{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.tk h4{font-size:15px;margin-bottom:12px;color:var(--l)}
.tk span{display:inline-block;margin:0 6px 8px 0;padding:6px 12px;border:1px solid var(--dline);border-radius:99px;font-size:13.5px;color:#d8d8dc}
/* cta */
.cta{background:var(--l);color:var(--k);padding:96px 0}
.cta h2{font-size:clamp(34px,6vw,68px);letter-spacing:-.035em;max-width:800px}
.cta p{margin:18px 0 32px;font-size:18px;max-width:520px;color:#2a3300}
/* footer */
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.ft{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:40px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}
footer h4{font-size:14px;margin-bottom:14px}
footer ul{list-style:none;margin:0;padding:0}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.pj .wrap{grid-template-columns:1fr;gap:36px}.pj.rev .tx{order:0}.pj .ch{max-width:none}
.sp{grid-template-columns:1fr}.sp .arr{transform:rotate(90deg);justify-self:start}.sp p{max-width:none}
.pr .row{grid-template-columns:1fr;gap:8px}.tk{grid-template-columns:repeat(2,1fr)}
.ft{grid-template-columns:1fr 1fr}}
@media(max-width:860px){nav ul{display:none}}
/* mobile */
@media(max-width:600px){
section{padding:64px 0}.pj{padding:64px 0}.wrap{padding:0 20px}.hero{padding:56px 0 52px}
.stg{padding:18px;min-height:0}.gym .ph{display:none}.gym .br{width:100%}.dsh{grid-template-columns:1fr}.sd{display:none}.g3{grid-template-columns:1fr 1fr}.g3 .fd:last-child{display:none}
.cars{gap:8px}.cars .ph,.cars .ph:nth-child(2){--pw:112px;border-radius:20px;padding:5px;margin:0}.cars .ph:nth-child(2){--pw:120px}.cars .sc{padding:2.6em .8em .8em;border-radius:16px}
.bk{grid-template-columns:1fr 1fr}.bk .pill{grid-column:span 2;text-align:center}.hh{padding-bottom:96px}.rms{padding-top:90px}.chip{display:none}.sn span{display:none}
.mb{padding:24px}.tk{grid-template-columns:1fr}.ctas .btn{width:100%;justify-content:center}.ft{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}

js:
(function(){
  var tabs=document.querySelectorAll('.fbar button');
  var items=Array.prototype.slice.call(document.querySelectorAll('#projects .pj'));
  function apply(f){
    var n=0;
    items.forEach(function(el){
      var show=f==='all'||el.getAttribute('data-cat').split(' ').indexOf(f)>-1;
      el.hidden=!show;
      if(show){
        var even=n%2===0;
        el.classList.toggle('lt',even);el.classList.toggle('dk',!even);el.classList.toggle('rev',!even);
        n++;
      }
    });
    tabs.forEach(function(t){t.setAttribute('aria-pressed',t.getAttribute('data-f')===f?'true':'false');});
  }
  tabs.forEach(function(t){t.addEventListener('click',function(){apply(t.getAttribute('data-f'));});});
  apply('all');
})();
